 57→function timeAgo(dateString: string): string {
 58→    const now = new Date();
 59→    const date = new Date(dateString);
 60→    const diffMs = now.getTime() - date.getTime();
 61→    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
 62→    const diffDays = Math.floor(diffHours / 24);
 63→
 64→    if (diffHours < 1) return 'hace un momento';
 65→    if (diffHours < 24) return `hace ${diffHours}h`;
 66→    if (diffDays === 1) return 'ayer';
 67→    return `hace ${diffDays} días`;
 68→}
