113→
114→function Step2({ animals, selectedId, onSelect }: { animals: Animal[]; selectedId: number | null; onSelect: (id: number) => void }) {
115→    const females = animals.filter((a) => a.sex === 'female' && a.birth_date);
116→    const [search, setSearch] = useState('');
117→    const filtered = females.filter((a) => a.crotal_code.includes(search) || (a.name && a.name.toLowerCase().includes(search.toLowerCase())));
118→
119→    return (
120→        <div className="flex flex-col gap-4">
121→            <h2 className="text-2xl font-bold">Seleccionar madre</h2>
122→            <p className="text-sm leading-[1.4] text-[#757575]">Selecciona la hembra que es madre del animal nacido.</p>
123→            <div className="flex gap-2">
124→                <input
125→                    type="text"
126→                    value={search}
127→                    onChange={(e) => setSearch(e.target.value)}
128→                    placeholder="Buscar por crotal o nombre..."
129→                    className="h-[52px] flex-1 bg-[#F5F5F5] px-[18px] text-base md:text-sm"
130→                />
131→                <button
132→                    onClick={() => router.visit('/scanner?returnTo=/nacimientos/crear')}
133→                    className="flex size-[52px] shrink-0 items-center justify-center border-2 border-black"
134→                    title="Escanear crotal"
135→                >
136→                    <Camera className="size-5" />
137→                </button>
138→            </div>
139→            <div className="flex flex-col gap-2">
140→                {filtered.map((a) => {
141→                    const age = Math.floor((Date.now() - new Date(a.birth_date).getTime()) / (365.25 * 24 * 60 * 60 * 1000));
142→                    return (
143→                        <button
144→                            key={a.id}
145→                            onClick={() => onSelect(a.id)}
146→                            className={`flex items-center gap-3 border-2 p-3 text-left ${selectedId === a.id ? 'border-[#E53935] bg-[#FFF5F5]' : 'border-black'}`}
147→                        >
148→                            {selectedId === a.id && <Check className="size-5 shrink-0 text-[#E53935]" />}
149→                            <div className="flex-1">
150→                                <p className="text-sm font-bold">{a.crotal_code}</p>
151→                                <p className="text-xs text-[#757575]">{a.breed} · {age} años{a.name ? ` · ${a.name}` : ''}</p>
152→                            </div>
153→                        </button>
154→                    );
155→                })}
156→            </div>
157→        </div>
158→    );
159→}
160→
161→function Step3({ animals, selectedId, onSelect, onSkip }: { animals: Animal[]; selectedId: number | null; onSelect: (id: number) => void; onSkip: () => void }) {
162→    const males = animals.filter((a) => a.sex === 'male');
163→    const [showParents, setShowParents] = useState(false);
164→
165→    return (
166→        <div className="flex flex-col gap-4">
167→            <h2 className="text-2xl font-bold">Padre (opcional)</h2>
168→            <p className="text-sm leading-[1.4] text-[#757575]">Si conoces al padre, selecciónalo. Puedes omitir este paso.</p>
169→            <button onClick={onSkip} className="w-full border-2 border-black py-3 text-center text-sm font-semibold">
170→                Omitir este paso
171→            </button>
172→            {!showParents && (
173→                <button
174→                    onClick={() => setShowParents(true)}
175→                    className="flex w-full items-center justify-center gap-2 border-2 border-black bg-[#F5F5F5] py-3 text-center text-sm font-semibold"
176→                >
177→                    Ver Padres <ChevronDown className="size-4" />
178→                </button>
179→            )}
180→            {showParents && males.map((a) => (
181→                <button
182→                    key={a.id}
183→                    onClick={() => onSelect(a.id)}
184→                    className={`flex items-center gap-3 border-2 p-3 text-left ${selectedId === a.id ? 'border-[#E53935] bg-[#FFF5F5]' : 'border-black'}`}
185→                >
186→                    {selectedId === a.id && <Check className="size-5 shrink-0 text-[#E53935]" />}
187→                    <div>
188→                        <p className="text-sm font-bold">{a.crotal_code}</p>
189→                        <p className="text-xs text-[#757575]">{a.breed}{a.name ? ` · ${a.name}` : ''}</p>
190→                    </div>
191→                </button>
192→            ))}
193→        </div>
194→    );
195→}
196→
197→function Step4({ motherBreed, calves, onUpdate }: { motherBreed: string; calves: CalfData[]; onUpdate: (calves: CalfData[]) => void }) {
198→    const today = new Date().toISOString().split('T')[0];
199→    const updateCalf = (index: number, field: keyof CalfData, value: string) => {
200→        const updated = [...calves];
201→        updated[index] = { ...updated[index], [field]: value };
202→        onUpdate(updated);
203→    };
204→    const addCalf = () => {
205→        onUpdate([...calves, { sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
206→    };
207→    const removeCalf = (index: number) => {
208→        if (calves.length > 1) onUpdate(calves.filter((_, i) => i !== index));
209→    };
210→
211→    return (
212→        <div className="flex flex-col gap-4">
213→            <h2 className="text-2xl font-bold">Datos de la cría</h2>
214→            {calves.map((calf, i) => {
215→                const daysAgo = Math.floor((Date.now() - new Date(calf.birth_date).getTime()) / (1000 * 60 * 60 * 24));
216→                return (
217→                    <div key={i} className="flex flex-col gap-3 border-2 border-black p-4">
218→                        <div className="flex items-center justify-between">
219→                            <span className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Cría {calves.length > 1 ? i + 1 : ''}</span>
220→                            {calves.length > 1 && (
221→                                <button onClick={() => removeCalf(i)} className="text-xs text-[#E53935]">Eliminar</button>
222→                            )}
223→                        </div>
224→                        <div>
225→                            <label className="text-xs font-semibold text-[#757575]">Fecha de nacimiento</label>
226→                            <input type="date" value={calf.birth_date} onChange={(e) => updateCalf(i, 'birth_date', e.target.value)} className="mt-1 h-[44px] w-full min-w-0 bg-[#F5F5F5] px-3 text-base md:text-sm" />
227→                            {daysAgo > 7 && <p className="mt-1 text-xs font-medium text-[#E65100]">Supera el plazo legal de 7 días. Se recomienda registrarlo cuanto antes.</p>}
228→                        </div>
229→                        <div>
230→                            <label className="text-xs font-semibold text-[#757575]">Sexo</label>
231→                            <div className="mt-1 flex gap-0">
232→                                {(['female', 'male'] as const).map((s) => (
233→                                    <button key={s} onClick={() => updateCalf(i, 'sex', s)} className={`flex-1 border-2 border-black py-2 text-xs font-bold ${calf.sex === s ? 'bg-black text-white' : ''}`}>
234→                                        {s === 'female' ? 'Hembra' : 'Macho'}
235→                                    </button>
236→                                ))}
237→                            </div>
238→                        </div>
239→                        <div>
240→                            <label className="text-xs font-semibold text-[#757575]">Raza</label>
241→                            <input type="text" value={calf.breed} onChange={(e) => updateCalf(i, 'breed', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-base md:text-sm" />
242→                        </div>
243→                        <div>
244→                            <label className="text-xs font-semibold text-[#757575]">Nombre (opcional)</label>
245→                            <input type="text" value={calf.name} onChange={(e) => updateCalf(i, 'name', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-base md:text-sm" placeholder="Ej: Txuri" />
246→                        </div>
247→                    </div>
248→                );
249→            })}
250→            <button onClick={addCalf} className="w-full border-2 border-black py-3 text-center text-sm font-semibold">
251→                + Añadir otra cría
252→            </button>
253→        </div>
254→    );
255→}
256→
257→function Step5({ sub, mother, father, calves, animals, onEditStep }: { sub: SubExploitation; mother: number; father: number | null; calves: CalfData[]; animals: Animal[]; onEditStep: (step: number) => void }) {
258→    const motherAnimal = animals.find((a) => a.id === mother);
259→    const fatherAnimal = father ? animals.find((a) => a.id === father) : null;
260→    const oldestCalfDaysAgo = Math.max(...calves.map((c) => Math.floor((Date.now() - new Date(c.birth_date).getTime()) / (1000 * 60 * 60 * 24))));
261→    const withinLegalDeadline = oldestCalfDaysAgo <= 7;
262→
263→    return (
264→        <div className="flex flex-col gap-4">
265→            <h2 className="text-2xl font-bold">Resumen</h2>
266→            <div className="flex flex-col gap-3 border-2 border-black p-4">
267→                <div className="flex items-start justify-between">
268→                    <div>
269→                        <p className="text-xs text-[#757575]">Subexplotación</p>
270→                        <p className="text-sm font-bold">{speciesLabels[sub.species]} · {sub.exploitation_type}</p>
271→                    </div>
272→                    <button onClick={() => onEditStep(0)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
273→                        <Pencil className="size-3" /> Editar
274→                    </button>
275→                </div>
276→                <div className="flex items-start justify-between">
277→                    <div>
278→                        <p className="text-xs text-[#757575]">Madre</p>
279→                        <p className="text-sm font-bold">{motherAnimal?.crotal_code} {motherAnimal?.name ? `(${motherAnimal.name})` : ''}</p>
280→                    </div>
281→                    <button onClick={() => onEditStep(1)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
282→                        <Pencil className="size-3" /> Editar
283→                    </button>
284→                </div>
285→                <div className="flex items-start justify-between">
286→                    <div>
287→                        <p className="text-xs text-[#757575]">Padre</p>
288→                        <p className="text-sm font-bold">{fatherAnimal ? `${fatherAnimal.crotal_code} ${fatherAnimal.name ? `(${fatherAnimal.name})` : ''}` : 'No indicado'}</p>
289→                    </div>
290→                    <button onClick={() => onEditStep(2)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
291→                        <Pencil className="size-3" /> Editar
292→                    </button>
293→                </div>
294→                <div className="mt-2 border-t-2 border-black pt-3">
295→                    <div className="flex items-start justify-between">
296→                        <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Crías ({calves.length})</p>
297→                        <button onClick={() => onEditStep(3)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
298→                            <Pencil className="size-3" /> Editar
299→                        </button>
300→                    </div>
301→                    {calves.map((c, i) => (
