524→    const [subExploitation, setSubExploitation] = useState<SubExploitation | null>(null);
525→    const [motherId, setMotherId] = useState<number | null>(null);
526→    const [fatherId, setFatherId] = useState<number | null>(null);
527→    const [calves, setCalves] = useState<CalfData[]>([]);
528→    const [submitting, setSubmitting] = useState(false);
529→    const [result, setResult] = useState<{ reference_code: string; calves: Array<{ name: string | null; sex: string; crotal: string }>; new_capacity: number; max_capacity: number } | null>(() => {
530→        if (success?.reference_code) {
531→            return {
532→                reference_code: success.reference_code,
533→                calves: success.calves || [],
534→                new_capacity: success.new_capacity || 0,
535→                max_capacity: 0,
536→            };
537→        }
538→        return null;
539→    });
540→
541→    const today = new Date().toISOString().split('T')[0];
542→
543→    const handleSubSelect = (sub: SubExploitation) => {
544→        setSubExploitation(sub);
545→        const motherBreed = sub.animals.find((a) => a.sex === 'female')?.breed || '';
546→        setCalves([{ sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
547→        setStep(1);
548→    };
549→
550→    const handleMotherSelect = (id: number) => {
551→        setMotherId(id);
552→        const mother = subExploitation?.animals.find((a) => a.id === id);
553→        if (mother) {
554→            setCalves((prev) => prev.map((c) => ({ ...c, breed: mother.breed })));
555→        }
556→    };
557→
558→    const handleSubmit = () => {
559→        if (!subExploitation || !motherId) return;
560→        setSubmitting(true);
561→
562→        router.post('/nacimientos', {
563→            sub_exploitation_id: subExploitation.id,
564→            mother_id: motherId,
565→            father_id: fatherId,
566→            birth_type: calves.length > 1 ? 'multiple' : 'simple',
567→            calf_count: calves.length,
568→            calves: calves.map((c) => ({
569→                sex: c.sex,
570→                breed: c.breed,
571→                name: c.name || null,
572→                birth_date: c.birth_date,
573→            })),
574→        }, {
575→            onSuccess: (page) => {
576→                const successData = (page.props as any).success;
577→                if (successData) {
578→                    setResult({
579→                        reference_code: successData.reference_code,
580→                        calves: successData.calves || [],
581→                        new_capacity: successData.new_capacity || 0,
582→                        max_capacity: subExploitation.max_capacity,
583→                    });
584→                    setStep(5);
585→                }
586→            },
587→            onError: () => setSubmitting(false),
588→        });
589→    };
590→
591→    const canNext = () => {
592→        if (step === 0) return !!subExploitation;
593→        if (step === 1) return !!motherId;
594→        if (step === 3) return calves.every((c) => c.birth_date && c.sex && c.breed);
595→        return true;
596→    };
597→
598→    return (
599→        <AppLayout breadcrumbs={breadcrumbs}>
