619→                {step === 0 && exploitation && <Step1 subExploitations={exploitation.sub_exploitations} onSelect={handleSubSelect} />}
620→                {step === 1 && subExploitation && <Step2 animals={subExploitation.animals} selectedId={motherId} onSelect={handleMotherSelect} />}
621→                {step === 2 && subExploitation && <Step3 animals={subExploitation.animals} selectedId={fatherId} onSelect={setFatherId} onSkip={() => { setFatherId(null); setStep(3); }} />}
622→                {step === 3 && subExploitation && (
